using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using TrootWindow.Api.Data; namespace TrootWindow.Api.Controllers;[ApiController][Route("api/jobs")]public sealed class JobsController(AppDbContext db):ControllerBase{[HttpGet]public async Task<IActionResult> Get([FromQuery]string?q,[FromQuery]string?category,[FromQuery]WorkMode?mode,[FromQuery]int page=1,[FromQuery]int pageSize=20,CancellationToken ct=default){page=Math.Clamp(page,1,10000);pageSize=Math.Clamp(pageSize,1,50);var x=db.Jobs.AsNoTracking().Where(j=>j.Status==JobStatus.Published);if(!string.IsNullOrWhiteSpace(q)){q=q.Trim();x=x.Where(j=>j.Title.Contains(q)||j.EmployerName.Contains(q)||j.Location.Contains(q)||j.Category.Contains(q)||j.Requirements.Contains(q));}if(!string.IsNullOrWhiteSpace(category)&&category!="All")x=x.Where(j=>j.Category==category);if(mode.HasValue)x=x.Where(j=>j.Mode==mode);return Ok(await x.OrderByDescending(j=>j.EmployerVerified).ThenByDescending(j=>j.CreatedAt).Skip((page-1)*pageSize).Take(pageSize).ToListAsync(ct));}[HttpGet("{id:guid}")]public async Task<IActionResult> One(Guid id,CancellationToken ct)=>OkOr404(await db.Jobs.AsNoTracking().FirstOrDefaultAsync(j=>j.Id==id&&j.Status==JobStatus.Published,ct));[HttpPost][Microsoft.AspNetCore.RateLimiting.EnableRateLimiting("public")]public async Task<IActionResult>Create(CreateJobRequest r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.Phone)&&string.IsNullOrWhiteSpace(r.WhatsApp)&&string.IsNullOrWhiteSpace(r.Email))return BadRequest(new{message="At least one contact method is required."});var j=new Job{Id=Guid.NewGuid(),Title=r.Title.Trim(),EmployerName=r.EmployerName.Trim(),Location=r.Location.Trim(),Category=r.Category.Trim(),Mode=r.Mode,Pay=r.Pay.Trim(),Description=r.Description.Trim(),Requirements=r.Requirements.Trim(),Phone=r.Phone?.Trim(),WhatsApp=r.WhatsApp?.Trim(),Email=r.Email?.Trim()};db.Jobs.Add(j);await db.SaveChangesAsync(ct);return Accepted(new{id=j.Id,status=j.Status});}private IActionResult OkOr404(Job? j)=>j is null?NotFound():Ok(j);}